#!/usr/bin/env python3
"""Make Reels direction-aware, hysteresis-controlled and less wasteful while swiping."""
from pathlib import Path

OLD_DECL="var reduce=matchMedia('(prefers-reduced-motion: reduce)'), conn=navigator.connection||{}, cards=[], states=new WeakMap(), active=null, suspended=!!window.__mm45Suspended, disposed=false, scheduled=false, muted=true, memoryGb=Number(navigator.deviceMemory||4), networkType=String(conn.effectiveType||'').toLowerCase(), networkOnline=navigator.onLine!==false, networkValidated=true, networkMetered=false, downKbps=0, powerSaving=false, pressure=0, resumeTimer=0;"
NEW_DECL="var reduce=matchMedia('(prefers-reduced-motion: reduce)'), conn=navigator.connection||{}, cards=[], states=new WeakMap(), active=null, suspended=!!window.__mm45Suspended, disposed=false, scheduled=false, muted=true, memoryGb=Number(navigator.deviceMemory||4), networkType=String(conn.effectiveType||'').toLowerCase(), networkOnline=navigator.onLine!==false, networkValidated=true, networkMetered=false, downKbps=0, powerSaving=false, pressure=0, resumeTimer=0, lastScrollTop=0, scrollDirection=1, activeRatio=0, activateTimer=0, scrollRaf=0;"

OLD_BUDGET="function budget(){var i=cards.indexOf(active),constrained=conservative||powerSaving||networkMetered||!networkValidated,keepAhead=pressure>=10||powerSaving?0:(fastNetwork&&memoryGb>=4?2:1);cards.forEach(function(c,n){var st=states.get(c);if(!st)return;if(i<0){scheduleRelease(st,300);return;}if(!networkOnline||!networkValidated){if(c===active)attach(st,'metadata','low');else scheduleRelease(st,200);return;}if(!isReels()||suspended||document.hidden){if(c===active){st.v.pause();attach(st,'metadata','low');}else scheduleRelease(st,300);return;}var distance=n-i;if(distance===0)attach(st,'auto','high');else if(distance===1)attach(st,constrained?'metadata':'auto',constrained?'low':'high');else if(distance===-1)attach(st,'metadata','low');else if(distance>1&&distance<=keepAhead)attach(st,'metadata','low');else scheduleRelease(st,releaseDelay);});}"
NEW_BUDGET="function budget(){var i=cards.indexOf(active),constrained=conservative||powerSaving||networkMetered||!networkValidated,keepAhead=pressure>=10||powerSaving?0:(fastNetwork&&memoryGb>=4?2:1),direction=scrollDirection>=0?1:-1;cards.forEach(function(c,n){var st=states.get(c);if(!st)return;if(i<0){scheduleRelease(st,300);return;}if(!networkOnline||!networkValidated){if(c===active)attach(st,'metadata','low');else scheduleRelease(st,200);return;}if(!isReels()||suspended||document.hidden){if(c===active){st.v.pause();attach(st,'metadata','low');}else scheduleRelease(st,300);return;}var distance=n-i,forward=distance*direction;if(distance===0)attach(st,'auto','high');else if(forward===1)attach(st,constrained?'metadata':'auto',constrained?'low':'high');else if(forward===-1)attach(st,'metadata','low');else if(forward>1&&forward<=keepAhead)attach(st,'metadata','low');else scheduleRelease(st,releaseDelay);});}"

OLD_ACTIVATE="function activate(card){if(!card||!states.has(card)||!isReels())return;if(active===card){budget();return;}pauseAll();if(active)active.removeAttribute('data-mm46-active');active=card;card.dataset.mm46Active='1';var st=states.get(card);budget();start(st,false);}"
NEW_ACTIVATE="function activate(card){if(!card||!states.has(card)||!isReels())return;if(active===card){activeRatio=Math.max(activeRatio,.6);budget();return;}clearTimeout(activateTimer);pauseAll();if(active)active.removeAttribute('data-mm46-active');active=card;activeRatio=1;card.dataset.mm46Active='1';var st=states.get(card);budget();start(st,false);}"

OLD_INTERSECTION="var intersection=typeof IntersectionObserver==='function'?new IntersectionObserver(function(entries){if(!isReels()||suspended)return;var best=null;entries.forEach(function(e){if(e.isIntersecting&&e.intersectionRatio>.55&&(!best||e.intersectionRatio>best.intersectionRatio))best=e;});if(best)activate(best.target);},{root:feed,threshold:[0,.15,.4,.55,.8,1]}):null;"
NEW_INTERSECTION="function queueActivate(card,ratio,force){if(!card||!states.has(card)||!isReels())return;var visible=Number(ratio)||0;if(card===active){activeRatio=Math.max(activeRatio,visible);clearTimeout(activateTimer);budget();return;}if(!force&&active&&activeRatio>.38&&visible<.72)return;clearTimeout(activateTimer);activateTimer=setTimeout(function(){activateTimer=0;if(disposed||suspended||document.hidden||!isReels())return;activate(card);},force?16:78);}\nvar intersection=typeof IntersectionObserver==='function'?new IntersectionObserver(function(entries){if(!isReels()||suspended)return;var best=null,current=null;entries.forEach(function(e){if(e.target===active)current=e;if(e.isIntersecting&&e.intersectionRatio>.58&&(!best||e.intersectionRatio>best.intersectionRatio))best=e;});if(current)activeRatio=current.intersectionRatio;if(best)queueActivate(best.target,best.intersectionRatio,false);},{root:feed,threshold:[0,.2,.38,.58,.72,.9,1]}):null;"

OLD_REFRESH="function refreshMode(){var on=isReels();H.toggleAttribute('data-mm46-reels',on);dimensions();if(on){panel.open=true;refreshCards();if(active&&!blocked())start(states.get(active),false);}else{pauseAll();cards.forEach(function(c){var st=states.get(c);if(c===active)attach(st,'metadata','low');else scheduleRelease(st,300);});} }"
NEW_REFRESH="function refreshMode(){var on=isReels();H.toggleAttribute('data-mm46-reels',on);dimensions();if(on){lastScrollTop=feed.scrollTop||0;panel.open=true;refreshCards();if(active&&!blocked())start(states.get(active),false);}else{clearTimeout(activateTimer);delete H.dataset.mm438Scrolling;pauseAll();cards.forEach(function(c){var st=states.get(c);if(c===active)attach(st,'metadata','low');else scheduleRelease(st,300);});} }"

OLD_SCROLL="var scrollTimer=0;function scrollFallback(){if(intersection)return;clearTimeout(scrollTimer);scrollTimer=setTimeout(function(){if(cards.length)activate(cards[Math.max(0,Math.min(cards.length-1,Math.round(feed.scrollTop/feed.clientHeight)))]);},50);}"
NEW_SCROLL="var scrollTimer=0;function nearestCard(){if(!cards.length)return null;var height=feed.clientHeight||1,index=Math.max(0,Math.min(cards.length-1,Math.round((feed.scrollTop||0)/height)));return cards[index];}\nfunction settleScroll(){delete H.dataset.mm438Scrolling;var card=nearestCard();if(card)queueActivate(card,1,true);}\nfunction scrollFallback(){var top=feed.scrollTop||0;if(top>lastScrollTop+1)scrollDirection=1;else if(top<lastScrollTop-1)scrollDirection=-1;lastScrollTop=top;H.dataset.mm438Scrolling='1';if(!scrollRaf)scrollRaf=requestAnimationFrame(function(){scrollRaf=0;budget();});clearTimeout(scrollTimer);scrollTimer=setTimeout(settleScroll,intersection?110:55);}"

OLD_EVENTS="feed.addEventListener('scroll',scrollFallback,{passive:true});window.addEventListener('mm45:suspend',onSuspend);window.addEventListener('mm45:resume',onResume);window.addEventListener('mmapp:memory',memoryChanged);window.addEventListener('mmapp:foreground',foregroundChanged);window.addEventListener('mmapp:background',backgroundChanged);window.addEventListener('mmapp:runtime',runtimeChanged);window.addEventListener('mmapp:network',runtimeChanged);window.addEventListener('mmapp:power',powerChanged);window.addEventListener('online',networkChanged);window.addEventListener('offline',networkChanged);window.addEventListener('mm435:network',networkChanged);document.addEventListener('visibilitychange',visibility);document.addEventListener('keydown',keys);window.addEventListener('resize',dimensions);if(window.visualViewport)window.visualViewport.addEventListener('resize',dimensions);if(conn&&conn.addEventListener)conn.addEventListener('change',connectionChanged);"
NEW_EVENTS="feed.addEventListener('scroll',scrollFallback,{passive:true});if('onscrollend' in feed)feed.addEventListener('scrollend',settleScroll,{passive:true});window.addEventListener('mm45:suspend',onSuspend);window.addEventListener('mm45:resume',onResume);window.addEventListener('mmapp:memory',memoryChanged);window.addEventListener('mmapp:foreground',foregroundChanged);window.addEventListener('mmapp:background',backgroundChanged);window.addEventListener('mmapp:runtime',runtimeChanged);window.addEventListener('mmapp:network',runtimeChanged);window.addEventListener('mmapp:power',powerChanged);window.addEventListener('online',networkChanged);window.addEventListener('offline',networkChanged);window.addEventListener('mm435:network',networkChanged);document.addEventListener('visibilitychange',visibility);document.addEventListener('keydown',keys);window.addEventListener('resize',dimensions);if(window.visualViewport)window.visualViewport.addEventListener('resize',dimensions);if(conn&&conn.addEventListener)conn.addEventListener('change',connectionChanged);"

OLD_DESTROY="function destroy(){disposed=true;clearTimeout(resumeTimer);pauseAll();cards.forEach(function(c){release(states.get(c));});feedObserver.disconnect();modeObserver.disconnect();dialogObserver.disconnect();if(intersection)intersection.disconnect();clearTimeout(scrollTimer);window.removeEventListener('mm45:suspend',onSuspend);window.removeEventListener('mm45:resume',onResume);window.removeEventListener('mmapp:memory',memoryChanged);window.removeEventListener('mmapp:foreground',foregroundChanged);window.removeEventListener('mmapp:background',backgroundChanged);window.removeEventListener('mmapp:runtime',runtimeChanged);window.removeEventListener('mmapp:network',runtimeChanged);window.removeEventListener('mmapp:power',powerChanged);window.removeEventListener('online',networkChanged);window.removeEventListener('offline',networkChanged);window.removeEventListener('mm435:network',networkChanged);document.removeEventListener('visibilitychange',visibility);document.removeEventListener('keydown',keys);window.removeEventListener('resize',dimensions);if(window.visualViewport)window.visualViewport.removeEventListener('resize',dimensions);if(conn&&conn.removeEventListener)conn.removeEventListener('change',connectionChanged);}"
NEW_DESTROY="function destroy(){disposed=true;clearTimeout(resumeTimer);clearTimeout(activateTimer);clearTimeout(scrollTimer);if(scrollRaf)cancelAnimationFrame(scrollRaf);delete H.dataset.mm438Scrolling;pauseAll();cards.forEach(function(c){release(states.get(c));});feedObserver.disconnect();modeObserver.disconnect();dialogObserver.disconnect();if(intersection)intersection.disconnect();if('onscrollend' in feed)feed.removeEventListener('scrollend',settleScroll);window.removeEventListener('mm45:suspend',onSuspend);window.removeEventListener('mm45:resume',onResume);window.removeEventListener('mmapp:memory',memoryChanged);window.removeEventListener('mmapp:foreground',foregroundChanged);window.removeEventListener('mmapp:background',backgroundChanged);window.removeEventListener('mmapp:runtime',runtimeChanged);window.removeEventListener('mmapp:network',runtimeChanged);window.removeEventListener('mmapp:power',powerChanged);window.removeEventListener('online',networkChanged);window.removeEventListener('offline',networkChanged);window.removeEventListener('mm435:network',networkChanged);document.removeEventListener('visibilitychange',visibility);document.removeEventListener('keydown',keys);window.removeEventListener('resize',dimensions);if(window.visualViewport)window.visualViewport.removeEventListener('resize',dimensions);if(conn&&conn.removeEventListener)conn.removeEventListener('change',connectionChanged);}"

REPLACEMENTS=[
    (OLD_DECL,NEW_DECL),(OLD_BUDGET,NEW_BUDGET),(OLD_ACTIVATE,NEW_ACTIVATE),
    (OLD_INTERSECTION,NEW_INTERSECTION),(OLD_REFRESH,NEW_REFRESH),(OLD_SCROLL,NEW_SCROLL),
    (OLD_EVENTS,NEW_EVENTS),(OLD_DESTROY,NEW_DESTROY),
]

def patch_controller(path:Path)->None:
    text=path.read_text(encoding='utf-8')
    for old,new in REPLACEMENTS:
        count=text.count(old)
        assert count==1,f'{path}: expected one 4.37 anchor, found {count}: {old[:120]!r}'
        text=text.replace(old,new,1)
    path.write_text(text,encoding='utf-8')
